  "rk4": [
   "…なあ。 影の中にいると、お前の顔、よく見えないな。 …もうちょい、こっち。",
   "…Hey. In the shadows I can't see your face well. …A bit closer.",
   "K"
  ],
  "rj1": [
   "…夜の回廊は危ねえ。 俺の後ろを歩け。",
   "…The corridor at night is dangerous. Walk behind me.",
   "J"
  ],
  "rj2": [
   "…朔が守れねえ夜は、俺が守る。",
   "…On nights Saku can't protect you, I will.",
   "J"
  ],
  "rs1": [
   "月明かりが、柱の間に縞を描いていますね。",
   "The moonlight is drawing stripes between the pillars.",
   "S"
  ],
  "rs2": [
   "…影が騒ぐ夜は、僕のそばに。 …君の星は、僕が守ります。",
   "…On restless nights, stay by me. …I'll protect your star.",
   "S"
  ],
  "dj1": [
   "…夜明けか。 …お前と見る朝日は、悪くねえ。",
   "…Dawn, huh. …The sunrise with you isn't bad.",
   "J"
  ],
  "ds1": [
   "星が消えて、朝が来ます。 …でも、見えなくても、星はそこにありますよ。",
   "The stars fade and morning comes. …But even unseen, they are still there.",
   "S"
  ],
  "dk1": [
   "…朝だ。 影の時間は、おしまい。 …ちょっと、さみしいな。",
   "…Morning. Shadow time is over. …A little lonely.",
   "K"
  ],
  "tt1": [
   "おーい、殿下も紫苑様も、そろったぜ。",
   "Hey, His Highness and Lord Shion are both here.",
   "K"
  ],
  "tt2": [
   "帰る前に、少しだけ、お話しましょうか。",
   "Before you go, shall we talk a little?",
   "S"
  ],
  "tt3": [
   "…言いたいことがあるなら、今言え。",
   "…If there's something you want to say, say it now.",
   "J"
  ],
  "tt4": [
   "君の世界でも、どうか、健やかに。",
   "Please stay well, in your world too.",
   "S"
  ],
  "tt5": [
   "…またな。",
   "…See you.",
   "K"
  ],
  "tt6": [
   "…待ってるぞ。",
   "…I'll be waiting.",
   "J"
  ],
  "bk_p_pond": [
   "池の氷は、朝にはとける。 …お前が来た穴も、きっと消える。",
   "The ice melts by morning. …The hole you came through will be gone too.",
   "K"
  ],
  "bj_p_pond": [
   "二度と、氷の上を歩くな。 …次は、俺が抱えて渡る。",
   "Never walk on the ice again. …Next time, I'll carry you across.",
   "J"
  ],
  "bs_p_pond": [
   "冷たい水は、星の光をいちばんきれいに映すのです。",
   "Cold water reflects starlight most beautifully.",
   "S"
  ],
  "bj_p_room": [
   "左の格子窓から雪の風、右は炭の火。 …俺のそばが、一番あったかい。",
   "Snowy wind from the lattice window on the left, the charcoal fire on the right. …Beside me is the warmest.",
   "J"
  ],
  "bk_p_room": [
   "殿下の火鉢、勝手にあたると怒られるぞ。 …俺はいつもこっそりだけど。",
   "You'll get scolded for warming yourself at His Highness's brazier. …I always sneak it though.",
   "K"
  ],
  "bs_p_room": [
   "炭の香りに、白檀を混ぜてあります。 …殿下は、ああ見えて香りにうるさいのですよ。",
   "Sandalwood is mixed into the charcoal. …His Highness is particular about scents, despite appearances.",
   "S"
  ],
  "bs_p_stars": [
   "左は北の風、右は香炉。 …この台は、冷たさとあたたかさの境目なのです。",
   "The north wind on the left, the incense on the right. …This terrace is the border between cold and warm.",
   "S"
  ],
  "bj_p_stars": [
   "星なんぞ、紫苑に任せとけ。 …お前は、俺を見てろ。",
   "Leave the stars to Shion. …You look at me.",
   "J"
  ],
  "bk_p_stars": [
   "あの流れ星、願いごとしたか？ …俺は、もうした。",
   "Did you wish on that shooting star? …I already did.",
   "K"
  ],
  "bk_p_hall": [
   "松明の灯りが見えたら、柱の影に入れ。 …それだけ覚えとけ。",
   "When you see torchlight, get into a pillar's shadow. …Just remember that.",
   "K"
  ],
  "bj_p_hall": [
   "回廊の刺客は、全部、俺が片付ける。 …お前は、何も見なくていい。",
   "I'll deal with every assassin in the corridors. …You don't have to see any of it.",
   "J"
  ],
  "bs_p_hall": [
   "月の縞の中を歩くと、影がふたつになります。 …片方は、朔かもしれませんね。",
   "Walk through the moon's stripes and you cast two shadows. …One of them might be Saku.",
   "S"
  ],
  "bj_p_dawn": [
   "朝日が出れば、帰り道が開く。 …ちっ、太陽が恨めしいな。",
   "When the sun rises, your way home opens. …Tch, I resent the sun.",
   "J"
  ],
  "bs_p_dawn": [
   "朝の光に、池の輪が光っていますね。 …星の門です。",
   "The ring in the pond shines in the morning light. …The star gate.",
   "S"
  ],
  "bk_p_dawn": [
   "朝の空気、冷てえな。 …でも、お日様はあったかい。",
   "The morning air's cold. …But the sun is warm.",
   "K"
  ]
